using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
sealed partial class WorkspaceWindow {
 List<Dictionary<string,object>> OpenStudioWindows(){var list=new List<Dictionary<string,object>>();string dir=Path.Combine(SharedRoot,"OpenStudios"),live=Path.GetFullPath(Path.Combine(SharedRoot,"LiveWindows"))+Path.DirectorySeparatorChar;if(!Directory.Exists(dir))return list;foreach(string file in Directory.GetFiles(dir,"*.json")){try{var r=json.Deserialize<Dictionary<string,object>>(ReadShared(file));if(Convert.ToInt32(r["protocol"])!=1||!studios.ContainsKey(Convert.ToString(r["studio"]))||!String.IsNullOrEmpty(Convert.ToString(r["owner"])))continue;var process=Process.GetProcessById(Convert.ToInt32(r["pid"]));string folder=Path.GetFullPath(Convert.ToString(r["folder"]));if(process.HasExited||!r.ContainsKey("started")||DateTime.Parse(Convert.ToString(r["started"])).ToUniversalTime()!=process.StartTime.ToUniversalTime()||!String.Equals(process.MainModule.FileName,Convert.ToString(r["exe"]),StringComparison.OrdinalIgnoreCase)||!folder.StartsWith(live,StringComparison.OrdinalIgnoreCase)||!Directory.Exists(folder)||!File.Exists(Path.Combine(folder,"ready.json"))||items.Concat(detachedItems).Any(t=>t.process!=null&&!t.process.HasExited&&t.process.Id==process.Id))continue;ValidateStudio(Convert.ToString(r["studio"]),process.MainModule.FileName);list.Add(r);}catch{}}return list;}
 void RefreshDetachedMenu(){RefreshDetachedMenuBase();var windows=OpenStudioWindows();detachedMenu.Text="Open & detached studios";if(windows.Count==0)return;if(detachedItems.Count==0)detachedMenu.DropDownItems.Clear();else detachedMenu.DropDownItems.Add(new ToolStripSeparator());foreach(var r in windows){var record=r;string key=Convert.ToString(r["studio"]);var entry=new ToolStripMenuItem("Open "+studios[key]+" · "+(r.ContainsKey("name")?Convert.ToString(r["name"]):"Standalone window"));entry.DropDownItems.Add("Move live window into a tab",null,async(a,b)=>{try{await AdoptLiveWindow(record);}catch(Exception e){SetStatus("Window stayed open: "+e.Message);}});if(key!="companion")entry.DropDownItems.Add("Open an editable copy in a new tab",null,async(a,b)=>{try{await CopyLiveWindow(record);}catch(Exception e){SetStatus("Original stayed open: "+e.Message);}});detachedMenu.DropDownItems.Add(entry);}}
 async Task AdoptLiveWindow(Dictionary<string,object> record){if(items.Count>=12)throw new Exception("Close or detach an unused tab first.");int pid=Convert.ToInt32(record["pid"]);var current=OpenStudioWindows().FirstOrDefault(r=>Convert.ToInt32(r["pid"])==pid);if(current==null)throw new Exception("This window has closed or belongs to another Workscape.");string studio=Convert.ToString(current["studio"]);var tab=new WorkTab{id=Convert.ToString(current["id"]),studio=studio,title="Jago "+studios[studio],folder=Convert.ToString(current["folder"]),process=Process.GetProcessById(pid),page=new TabPage(),panel=new Panel{Dock=DockStyle.Fill},detached=true};tab.page.Controls.Add(tab.panel);tab.panel.Resize+=(s,e)=>ResizeTab(tab);detachedItems.Add(tab);await Reattach(tab);if(!tab.attached)throw new Exception("Attachment is still being checked. Your document remains in the same process.");SetStatus("Live window moved into a tab. Its document and undo history are retained.");}
 async Task CopyLiveWindow(Dictionary<string,object> record){var live=OpenStudioWindows().FirstOrDefault(r=>Convert.ToInt32(r["pid"])==Convert.ToInt32(record["pid"]));if(live==null)throw new Exception("This window is no longer standalone.");string folder=Convert.ToString(live["folder"]),snapshot=Path.Combine(folder,"snapshot.json");DateTime start=DateTime.UtcNow;Atomic(Path.Combine(folder,"command-"+Guid.NewGuid()+".json"),json.Serialize(new{type="capture"}));for(int i=0;i<120;i++){if(File.Exists(snapshot)&&File.GetLastWriteTimeUtc(snapshot)>=start)break;await Task.Delay(100);}if(!File.Exists(snapshot)||File.GetLastWriteTimeUtc(snapshot)<start)throw new Exception("The document could not be captured yet.");var data=json.Deserialize<Dictionary<string,object>>(ReadShared(snapshot));var tab=Add(Convert.ToString(live["studio"]),data["document"]);if(tab!=null)Start(tab);SetStatus("Editable copy opened. The original window remains independent; its undo history stays there.");}
 async Task ConnectedLaunchTest(){try{if(items.Count!=1||items[0].studio!="library")throw new Exception("Connected launch did not create exactly one Library tab");var tab=items[0];await ProbeChild(tab,"window.__workspaceTestResult=window.appReady?{ok:true}:{error:'Library not ready'}");await CloseChild(tab);Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks=new[]{"selected studio opens directly as one Workscape tab"}}));}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString()}));}allowClose=true;Close();}
 async Task LiveWindowTest(){try{Dictionary<string,object> record=null;for(int i=0;i<200&&record==null;i++){record=OpenStudioWindows().FirstOrDefault(r=>Convert.ToString(r["studio"])=="library");await Task.Delay(100);}if(record==null)throw new Exception("Standalone Library not discovered");int pid=Convert.ToInt32(record["pid"]);await AdoptLiveWindow(record);var tab=items.Single(t=>t.process.Id==pid);await CaptureTab(tab);string snapshot=ReadShared(Path.Combine(tab.folder,"snapshot.json"));if(!snapshot.Contains("Live window retained"))throw new Exception("Edited document lost");await ProbeChild(tab,"window.__workspaceTestResult=window.liveUndoSentinel===123?{ok:true}:{error:'Live JavaScript context lost'}");await ProbeChild(tab,"document.querySelector('#canvas').focus();JagoWorkspaceShortcut('z');window.__workspaceTestResult=state.layout.layers[0].x===window.liveOriginalX?{ok:true}:{error:'Undo history was lost'}");await Detach();if(tab.process.HasExited)throw new Exception("Detach closed live process");await Reattach(tab);await CaptureTab(tab);if(!ReadShared(Path.Combine(tab.folder,"snapshot.json")).Contains("Live window retained"))throw new Exception("Reattach lost edits");await CloseChild(tab);Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks=new[]{"independent studio discovered","same live process adopted","edited document retained","detach and reattach retain live document"}}));}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString()}));}allowClose=true;Close();}

 async Task FindPortableStudios(string rootFolder,Form owner,Action refresh){var found=await Task.Run(()=>{var candidates=new List<Tuple<string,string>>();var queue=new Queue<Tuple<string,int>>();queue.Enqueue(Tuple.Create(Path.GetFullPath(rootFolder),0));int checkedFolders=0;while(queue.Count>0&&checkedFolders++<2000){var node=queue.Dequeue();try{if((File.GetAttributes(node.Item1)&FileAttributes.ReparsePoint)!=0)continue;foreach(string key in studios.Keys)foreach(string name in StudioNames(key)){string path=Path.Combine(node.Item1,name);if(File.Exists(path))try{ValidateStudio(key,path);candidates.Add(Tuple.Create(key,path));}catch{}}if(node.Item2<4)foreach(string dir in Directory.GetDirectories(node.Item1))queue.Enqueue(Tuple.Create(dir,node.Item2+1));}catch{}}return candidates;});using(var picker=new Form{Text="Studios found · choose explicitly",Size=new System.Drawing.Size(980,620),StartPosition=FormStartPosition.CenterParent,BackColor=BackColor,ForeColor=ForeColor,Font=Font}){var list=new ListBox{Dock=DockStyle.Fill,HorizontalScrollbar=true};foreach(var item in found)list.Items.Add(studios[item.Item1]+" · "+StudioVersion(item.Item2)+" · "+item.Item2);var choose=new Button{Text="Use selected version",Dock=DockStyle.Bottom,Height=40,Enabled=found.Count>0};choose.Click+=(a,b)=>{if(list.SelectedIndex<0)return;var item=found[list.SelectedIndex];ChooseStudio(item.Item1,item.Item2);refresh();SetStatus("New "+studios[item.Item1]+" tabs use the selected release. Existing tabs keep their version.");};var label=new Label{Dock=DockStyle.Top,Height=55,Text=found.Count+" releases found within four folder levels. Nothing changes until you select a release. Junctions are skipped."};picker.Controls.Add(list);picker.Controls.Add(label);picker.Controls.Add(choose);picker.ShowDialog(owner);}}
}
